fn splitlines(a: Vec<String>, keepends: bool) -> Vec<Vec<String>> {
    let mut result = Vec::with_capacity(a.len());
    
    for s in a {
        let mut lines = Vec::new();
        
        if keepends {
            // When keepends is true, we keep the line endings
            // For simplicity, we'll split on '\n' and add it back to each line except the last
            let parts: Vec<&str> = s.split('\n').collect();
            
            for (i, part) in parts.iter().enumerate() {
                if i < parts.len() - 1 {
                    // Add newline back for all but the last line
                    lines.push(format!("{}{}", part, '\n'));
                } else if !part.is_empty() || parts.len() == 1 {
                    // Last line - only add if not empty or if it's the only line
                    lines.push(part.to_string());
                }
            }
            
            // Handle edge case where string ends with newline
            if s.ends_with('\n') && !lines.is_empty() {
                // The last element should be an empty string with newline
                let last_line = lines.pop().unwrap();
                if !last_line.ends_with('\n') {
                    lines.push(last_line);
                    lines.push("\n".to_string());
                } else {
                    lines.push(last_line);
                }
            }
        } else {
            // When keepends is false, we don't keep line endings
            // Split on '\n' and filter out empty strings at the end
            let parts: Vec<&str> = s.split('\n').collect();
            
            for part in parts {
                if !part.is_empty() || parts.len() == 1 {
                    lines.push(part.to_string());
                }
            }
        }
        
        // Ensure the inner list is non-empty (as required)
        if lines.is_empty() {
            lines.push(String::new());
        }
        
        result.push(lines);
    }
    
    result
}